  /// Creates the en namespace.
  const $OnboardingWelcomeEn();

  @override
  String title({required num count}) {
    if (count == 0) {
      return 'No welcome';
    }
    final $operands = PluralOperands.formatted(
      count,
      minimumFractionDigits: _enNumberDecimalPattern.minimumFractionDigits,
      maximumFractionDigits: _enNumberDecimalPattern.maximumFractionDigits,
    );
    if ($operands.i == 1 && $operands.v == 0) {
      return '${_enNumberDecimalPattern.format(count)} welcome';
    }
    return '${_enNumberDecimalPattern.format(count)} welcomes';
  }

  @override
  String get subtitle => 'Welcome subtitle';

  @override
  String get action => 'Welcome action';

  @override
  String get hint => 'Welcome hint';

  @override
  String get error => 'Welcome error';

  @override
  String empty({required String name}) => 'Welcome empty, $name';
}

